/* @lc app=leetcode id=3943 lang=kotlin */ class Solution { fun ch(m: HashMap<Long, Int>, v: Long, d: Int) = m.merge(v, d) { a, b -> a + b }.let { if (it == 0) m.remove(v) } fun numberOfPairs(nums1: IntArray, nums2: IntArray, queries: Array<IntArray>): IntArray = nums2.size.let { n -> 224.let { B -> ((n + B - 1) / B).let { nb -> nums2.map { it.toLong() }.toLongArray().let { a -> LongArray(nb).let { lz -> Array(nb) { HashMap<Long, Int>() }.also { mp -> a.indices.forEach { ch(mp[it / B], a[it], 1) } }.let { mp -> queries.mapNotNull { q -> if (q[0] == 1) q[1].let { x -> q[2].let { y -> q[3].toLong().let { v -> (if (x / B == y / B) (x..y).forEach { i -> ch(mp[i / B], a[i], -1).also { a[i] += v }.also { ch(mp[i / B], a[i], 1) } } else (x until (x / B + 1) * B).forEach { i -> ch(mp[i / B], a[i], -1).also { a[i] += v }.also { ch(mp[i / B], a[i], 1) } }.let { (y / B * B..y).forEach { i -> ch(mp[i / B], a[i], -1).also { a[i] += v }.also { ch(mp[i / B], a[i], 1) } } }.let { (x / B + 1 until y / B).forEach { b -> lz[b] += v } }) } } }.let { null } else q[1].let { tot -> (0 until nb).sumOf { b -> nums1.sumOf { u -> mp[b][tot - u - lz[b]] ?: 0 } } } }.toIntArray() } } } } } } }